                let count = 0;
                $.each(data.latest_notification_count, function( key, value ) {
                    if (value == cookieData) {
                        return false;
                    } else {
                        return count++;
                    }
                });
                data.latest_count_bell = count;
                if (cookieData != '') {
                    setNewsCount(data);             
                } else {
                    if (data.unix_datatime) {
                        setNotiCookie(_aajtakBKCookie, _aajtakBKCookieExp, data.unix_datatime);
